class Interval:
    @staticmethod
    def _as_interval(v):
        # interval library accepts interval[a,b] or interval[a]
        if isinstance(v, interval):
            return v
        return interval[v, v]

    @staticmethod
    def pow(x, y):
        xI = Interval._as_interval(x)
        yI = Interval._as_interval(y)

        # --- NEW: integer exponent fast-path (avoids log on negative bases) ---
        # Only if y is exactly a point interval with one component
        if len(yI) == 1 and yI[0][0] == yI[0][1]:
            yy = yI[0][0]
            # integer check (works for floats like 2.0, -3.0, etc.)
            if float(yy).is_integer():
                n = int(yy)

                if n == 0:
                    return interval[1.0, 1.0]
                if n < 0:
                    return Interval.pow(interval[1.0, 1.0] / xI, -n)

                out = xI
                for _ in range(n - 1):
                    out = out * xI
                return out
        # --- end NEW ---

        # fallback (your existing definition)
        return exp(yI * log(xI))



